  "knowledge": "Relative Humidity Implications",
  "description": "Illustrates relative humidity readings and their conservation implications.",
  "definition": "Ideal for mixed collections is 45-55%. Fluctuations greater than 5% within 24 hours are risky. Readings below 30% or above 65% indicate significant risk."
}

